    "default branch": "默认分支",
    "An existing private GitHub repository, in owner/repo form.": "已有的私有 GitHub 仓库，格式为 owner/repo。",
    "Empty uses the repository's default branch. Empty repositories are initialized by the first sync; other branches must already exist.": "留空使用仓库默认分支。空仓库会在首次同步时初始化；其他分支必须已存在。",
    "The GitHub repository is empty: leave Branch empty or use its default branch for the first sync": "GitHub 仓库为空：首次同步请将分支留空，或使用仓库默认分支",
    "The encrypted backup goes in <folder>/magpie/magpie.magpie-backup. Each update creates a commit.": "加密备份保存在 <folder>/magpie/magpie.magpie-backup。每次更新会创建一次提交。",
    "A fine-grained token for this repository with Contents: read and write. Kept on this computer, separately from the library's GitHub token.": "为此仓库配置细粒度 Token，授予 Contents 读写权限。仅保存在本机，与资源库的 GitHub Token 分开。",
    "Name the GitHub repository as owner/repo": "请按 owner/repo 格式填写 GitHub 仓库",
    "Enter a GitHub token with Contents read and write permission": "请输入具有 Contents 读写权限的 GitHub Token",
    "Links": "符号链接",
    "Restore saved settings and remove magpie?": "恢复已保存的设置并移除 magpie？",
    "Restore saved settings and remove magpie without contacting Aside? Close Aside first if it is running.": "要在不连接 Aside 的情况下恢复已保存的设置并移除 magpie 吗？如果 Aside 正在运行，请先关闭 Aside。",
    "Restore saved settings and remove magpie": "恢复已保存的设置并移除 magpie",
