    "Aside is unavailable. Save this model for its next start?": "无法连接 Aside。要保存此模型供下次启动使用吗？",
    "Save for next start": "保存供下次启动使用",
    "Saved for Aside's next start; the running model has not been changed": "已保存供 Aside 下次启动使用，当前运行模型未改变",
    "The magpie provider is missing; reconnect the provider without changing this selection": "magpie 提供方缺失，请重新接入提供方，当前模型选择不变",
    "Showing saved settings": "显示已保存的设置",
    "Aside's runtime could not be read; showing saved settings": "无法读取 Aside 当前运行状态，显示已保存的设置",
    "No verified restore point; select a native model before disconnecting": "没有已确认的恢复记录，请先选择原生模型再断开",
    "Image generation is configured, but Aside's image provider support has not been verified": "已配置图片生成，尚未验证 Aside 对此图片提供方的支持",
