    "The tokens and cost {name} has used go back to 0 together, and a new {n}-day cycle starts now.": "{name} 已用的 Token 和费用一起清零，并从现在开始新的 {n} 天周期。",
    "The tokens and cost {name} has used go back to 0 together. Calls so far in this window stop counting; it still resets {when}.": "{name} 已用的 Token 和费用一起清零，本周期内此前的调用不再计入；周期仍在 {when} 重置。",
