    "Add gateway key": "添加网关密钥",
    "Create a gateway key for each client. Usage is counted separately for each key.": "为每个客户端创建一个网关密钥，分别统计用量。",
    "Key holders see their usage and setup at": "密钥持有人可在此查看自己的用量和配置方法：",
    "Key page": "密钥页面",
    "Gateway keys are for other computers, and for a tunnel to this one such as Cloudflare Tunnel: they are added here once Share on local network is on. Agents on this computer need none.": "网关密钥给其他电脑用，也给连到这台电脑的隧道（如 Cloudflare Tunnel）用：打开「局域网共享」后在这里添加。这台电脑上的 Agent 不需要密钥。",
    "Gateway key name": "网关密钥名称",
    "Key name, e.g. Laptop": "密钥名称，例如笔记本",
    "Create": "创建",
    "Your own key (optional)": "自定义密钥（可选）",
    "Gateway key value": "网关密钥的值",
    "Leave empty and magpie makes a key. Or enter one your clients already send, from another gateway, so they keep working.": "留空则由 magpie 生成密钥。也可以填写客户端已经在用的密钥（例如从其他网关迁移过来的），客户端无需改动。",
    "Gateway key created. Clients that send this key reach magpie now.": "网关密钥已创建，发送这个密钥的客户端现在就能连接 magpie。",
    "Use a key between 8 and 256 characters": "密钥长度需在 8 到 256 个字符之间",
    "A key can have only letters, digits and ASCII symbols, no spaces": "密钥只能包含字母、数字和 ASCII 符号，不能有空格",
    "A key of your own can't start with sk-magpie-: leave the key empty and magpie makes one": "自定义密钥不能以 sk-magpie- 开头：留空即可由 magpie 生成",
    "Another gateway key already has this key": "已有其他网关密钥使用了这个密钥",
    "Gateway key created. Use Copy on its row to connect a client.": "网关密钥已创建，用该行的复制按钮配置客户端。",
