    "{agent} is connected to magpie · it stays on its own last pick; magpie's models join its {cmd}": "{agent} 已接入 magpie · 仍用它上次选的模型，magpie 的模型已加入 {cmd}",
    "via magpie": "经 magpie",
    "{agent} asks magpie for it": "{agent} 经 magpie 请求这个模型",
    "direct, not via magpie": "直连，不经 magpie",
    "off magpie": "不经 magpie",
    "{agent} as installed: magpie's endpoint and models come out": "{agent} 初始设置：移除 magpie 的地址和模型",
    "Take {agent} off magpie?": "让 {agent} 不再经过 magpie？",
    "restore the previous {field} selection": "还原原来的 {field} 选择",
    "Restores {agent}'s previous {field} selection. Magpie's provider and private credential are removed when neither executor nor planner uses them.": "还原 {agent} 原来的 {field} 选择。执行模型和规划模型都不再使用 magpie 时，移除它的服务商配置和专用密钥。",
    "Default is {agent} as installed: magpie's endpoint and models come out, and {agent} starts on its own default model. What it had before magpie isn't put back; Disconnect and restore does that.": "「默认」即 {agent} 的初始设置：移除 magpie 的地址和模型，{agent} 以自身默认模型启动。不还原接入前的设置，还原请用「断开并还原」。",
    "{model} is {agent}'s own model: {agent} asks {vendor} for it itself, with its own sign-in, not through magpie. Picking it takes {agent} off magpie, and it starts on {model}.": "{model} 是 {agent} 自带的模型：{agent} 用自己的登录直接向 {vendor} 请求，不经过 magpie。选择后 {agent} 断开 magpie，以 {model} 启动。",
    "「接入」 goes off, and {agent} is listed under Not set up with the agents not connected. Switch it on again to go back through magpie.": "「接入」将关闭，{agent} 列入「未设置」。再次打开「接入」即可重新经过 magpie。",
    "「接入」 goes off. Switch it on again to go back through magpie.": "「接入」将关闭，再次打开即可重新经过 magpie。",
    "Use default": "使用默认",
    "Use {model}": "使用 {model}",
    "{agent} no longer goes through magpie · on its own default": "{agent} 已不经过 magpie · 使用自身默认设置",
    "{agent} no longer goes through magpie; its own settings are back": "{agent} 已不再经过 magpie，原来的设置已还原",
    "Update to {v}": "更新到 {v}",
    "Updates with {cmd}": "通过 {cmd} 更新",
    "Updates with {cmd}, as administrator: Windows asks first": "通过 {cmd} 以管理员身份更新：Windows 会先询问",
    "{agent} is installed in {prefix}, which only an administrator can change, and the administrator prompt was declined.": "{agent} 安装在 {prefix}，这个目录只有管理员能修改，而管理员授权提示被拒绝了。",
    "{agent} is installed in {prefix}, which only an administrator can change, and magpie couldn't ask Windows for one ({why}).": "{agent} 安装在 {prefix}，这个目录只有管理员能修改，而 magpie 没能向 Windows 请求管理员权限（{why}）。",
    "Update again and allow it, run {cmd} in a terminal opened as administrator, or move npm's global folder to one of your own (npm config set prefix \"%APPDATA%\\npm\") and install {agent} again.": "请再次更新并允许授权，或在以管理员身份打开的终端里运行 {cmd}，或把 npm 的全局目录改到自己的文件夹（npm config set prefix \"%APPDATA%\\npm\"）后重新安装 {agent}。",
    "npm installs into {prefix} here, which only an administrator can change: run the npm commands in a terminal opened as administrator, or first move npm's global folder to one of your own (npm config set prefix \"%APPDATA%\\npm\").": "这里 npm 会安装到 {prefix}，这个目录只有管理员能修改：请在以管理员身份打开的终端里运行 npm 命令，或先把 npm 的全局目录改到自己的文件夹（npm config set prefix \"%APPDATA%\\npm\"）。",
    "{agent} updated to {v}": "{agent} 已更新到 {v}",
    "{agent} is already being updated": "{agent} 正在更新",
    "{n} agents have updates: {names}": "{n} 个 Agent 有新版本：{names}",
    "Updating {agent}… ({i} of {n})": "正在更新 {agent}…（{i}/{n}）",
    "{agent} has an update": "{agent} 有新版本",
    "Every agent is up to date": "所有 Agent 都已是最新",
    "{ok} of {n} agents updated · {failed} didn't: {names}": "{n} 个 Agent 中已更新 {ok} 个 · {failed} 个未成功：{names}",
    "{agent} updated: {from} → {v}": "{agent} 已更新：{from} → {v}",
    "{n} agents updated: {list}": "已更新 {n} 个 Agent：{list}",
    "{ok} of {n} agents updated: {list} · {failed} didn't: {names}": "{n} 个 Agent 中已更新 {ok} 个：{list} · {failed} 个未成功：{names}",
    "Install another agent ({n})": "安装其他 Agent（{n}）",
    "CLI not found": "未找到 CLI",
    "Not on your terminal's PATH": "不在终端的 PATH 里",
    "magpie found {agent} {v} at {path}. That folder is one magpie looks in, but your terminal's PATH doesn't have it, so a terminal won't find {agent} there. If it was left behind by an uninstall, delete it.": "magpie 在 {path} 找到了 {agent} {v}。这个文件夹 magpie 会去找，但终端的 PATH 里没有它，所以终端里找不到这个 {agent}。如果它是卸载时没删干净留下的，把它删掉即可。",
    "{agent}'s settings are still here ({path}), but its command-line program isn't found: it may have been uninstalled. Install another agent, below the list, has its install command.": "{agent} 的配置还在（{path}），但找不到它的命令行程序，可能已被卸载。列表下方的「安装其他 Agent」里有它的安装命令。",
    "{agent}'s settings are still here ({path}), but its command-line program isn't found: it may have been uninstalled. Its settings are offered here again once it is installed.": "{agent} 的配置还在（{path}），但找不到它的命令行程序，可能已被卸载。重新安装后，这里会再显示它的设置。",
    "{agent}'s settings are still here, but its command-line program isn't found": "{agent} 的配置还在，但找不到它的命令行程序",
    "Run a command in a terminal, then come back: magpie lists the agent here once it is installed. The npm commands need Node.js (nodejs.org).": "在终端运行任一命令，安装后会列在这里。npm 命令需要 Node.js（nodejs.org）。",
    "Run a command in a terminal, then come back: magpie lists the agent here once it is installed.": "在终端运行任一命令，安装后会列在这里。",
    "No Node.js was found here, so the npm commands install it with nvm first.": "本机未找到 Node.js，npm 命令会先用 nvm 安装它。",
    "On a Mac, nvm needs Xcode's Command Line Tools: if it asks for them, run xcode-select --install, then the command again.": "Mac 上 nvm 需要 Xcode 命令行工具：如有提示，先运行 xcode-select --install，再重新运行命令。",
    "No Node.js was found here, so the npm commands install it with winget first; run them in PowerShell. If npm isn't found after Node.js is installed, open a new terminal and run the npm install again.": "本机未找到 Node.js，npm 命令会先用 winget 安装它，请在 PowerShell 中运行。若装好 Node.js 后仍找不到 npm，请打开新终端重新运行 npm 安装。",
    "Node.js + npm": "Node.js + npm",
