    "the chat's model; for a Claude chat, its provider's model of the tier": "对话的模型；对话用 Claude 模型时，用其供应商的该档位模型",
    "not set": "未设置",
    "Not set": "未设置",
    "Same as model": "同主模型",
    "{agent} stays signed in; magpie just stops offering it": "{agent} 仍保持登录，只是 magpie 不再提供它",
