    "Detect agents in WSL": "检测 WSL 中的 Agent",
    "Looks in running WSL distros for agents to set up, their sessions and Claude Code; off, WSL is never asked anything and the agents found there are no longer shown": "在运行中的 WSL 发行版里查找可接入的 Agent、它们的会话和 Claude Code；关闭后不再向 WSL 询问任何内容，之前在那里找到的 Agent 也不再显示",
    "Screen on too": "屏幕也常亮",
