    "A notification when masking swaps a value for the first time: its kind and how many, never the value itself": "首次脱敏某个值时通知：只说类型和个数，从不显示值本身",
    "A notification when Claude Code, Codex, OpenCode or another agent going through magpie finishes a task that ran at least this long": "Claude Code、Codex、OpenCode 等经由 magpie 的智能体完成一个至少跑了这么久的任务时通知",
    "Notifications are turned off for magpie in the system's settings": "系统设置里关闭了 magpie 的通知",
    "Notifications can't be shown on this system": "此系统无法显示通知",
    "Share used": "已用比例",
    "Amount": "金额",
    "Provider in model names": "模型名带供应商",
    "“Provider in model names” is one setting for every provider": "「模型名带供应商」是全局设置，对所有供应商生效",
    "Change in Settings": "在设置中修改",
    "Not on names I set": "自定义名称不带供应商",
    "Agents’ lists show “{label}”": "Agent 的模型列表里显示为「{label}」",
    "Changes nothing in {agents}: magpie’s names don’t reach their model lists": "对 {agents} 不起作用：它们的模型列表里没有 magpie 给的名称",
    "Codex subagents on any model": "Codex 子代理可用任意模型",
    "Long conversations": "长对话",
    "Full window": "完整窗口",
    "Codex background compaction": "Codex 后台压缩",
    "Codex 0.163 and later summarise while a turn goes on, past the share of the window typed (65% when empty); a value set in its own config stays": "Codex 0.163 起在一轮进行中就在后台总结，超过这里填的窗口占比时开始（留空为 65%）；它配置里自己设的值不动",
    "Background compaction at": "后台压缩阈值",
    "Background compaction at: {v} is not a percent from 1 to 100": "后台压缩阈值：{v} 不是 1 到 100 的百分比",
    "{who}: the share needs Codex 0.163 or later; until it's updated magpie writes only async_compaction = true, at 65%": "{who}：阈值需要 Codex 0.163 或更新；更新之前 magpie 只写 async_compaction = true，按 65%",
    "Codex's config.toml sets {keys}, read before Long conversations": "Codex 的 config.toml 设了 {keys}，Codex 先读它再读「长对话」，所以按它压缩",
    "Take it out": "拿掉它",
    "Codex compacts {model} at 90% of its {n} window, before Long conversations; set a larger one in its provider's Context window": "magpie 告诉 Codex {model} 的窗口是 {n}，所以 Codex 在它的 90% 处压缩，不等「长对话」；更大的窗口在它服务商的「上下文窗口」里设",
