    "Same as the session": "跟随当前会话",
    "Codex memories model": "Codex 记忆整理模型",
    "Same as the lead": "跟主代理一样",
    "The lead picks each subagent's model; one it names none for runs on the lead's model ({model}). A resumed subagent stays on the model it started on. A model picked here holds every subagent to it, even when the lead names another.": "主代理为每个子代理选模型；主代理没指定时，子代理用主代理的模型（{model}）。恢复的子代理仍用它最初的模型。在这里选定一个模型，所有子代理都固定用它，主代理指定了别的也一样。",
    "The lead picks each subagent's model; one it names none for runs on the lead's model. A resumed subagent stays on the model it started on. A model picked here holds every subagent to it, even when the lead names another.": "主代理为每个子代理选模型；主代理没指定时，子代理用主代理的模型。恢复的子代理仍用它最初的模型。在这里选定一个模型，所有子代理都固定用它，主代理指定了别的也一样。",
    "Every subagent runs on this model, even when the lead names another. Same as the lead gives the pick back to the lead.": "所有子代理都用这个模型，主代理指定了别的也一样。选“跟主代理一样”就把选择交还给主代理。",
    "Codex's config still starts subagents on {model} when the lead names none; picking here replaces it.": "Codex 配置里还写着：主代理没指定时，子代理用 {model}。在这里选一次就会替换掉它。",
    "{model}, or another the lead picks for a subagent": "{model}，或主代理给子代理另选的模型",
    "the lead's model, or another the lead picks for a subagent": "主代理正在用的模型，或主代理给子代理另选的模型",
    "Codex subagent model": "Codex 子代理模型",
    "{agent} settings": "{agent} 设置",
    "In {agent}'s settings, on the Agents page": "在 Agent 页的 {agent} 设置里",
    "no title, nothing sent": "不生成标题，不发出请求",
    "no description, nothing sent": "不生成描述，不发出请求",
    "A GPT lead spawns subagents on magpie’s other models. New threads only; Codex’s own multi_agent_v2 still wins": "GPT 主代理可在 magpie 的其他模型上开子代理。仅对新会话生效；Codex 自身的 multi_agent_v2 优先",
    "Codex's own multi_agent_v2 is on in the config magpie routes, which takes over the multi-agent V1 magpie's models ask for; turn it off in Codex's config to run subagents on magpie's models.": "Codex 自身的 multi_agent_v2 在 magpie 接管的配置里开着，会盖过 magpie 模型所需的 multi-agent V1；请在 Codex 的配置里把它关掉，才能让子代理跑在 magpie 的模型上。",
    "Codex's multi-agent V1 is on, but magpie couldn't read Codex's config to check its own multi_agent_v2.": "Codex 的 multi-agent V1 已开启，但 magpie 读不到 Codex 的配置，无法确认它自己的 multi_agent_v2。",
    "$ USD": "$ 美元",
