    "What a cost — the Usage page's, the tray panel's, the TUI's and the CLI's — is shown as; a vendor's own balance, already in its own currency, is never converted": "用量页、托盘面板、TUI 和命令行的费用按此币种显示；厂商余额保持其原币种，不换算",
