    "Same as above, {at}": "与上面相同，{at}",
    "Same as above, off": "与上面相同，已关闭",
    "Give accounts different times and one window starts as another runs out.": "给各账号设不同的时间，一个窗口用完时另一个刚好开启。",
    "{who}'s time of day": "{who} 的预热时间",
