    "Own": "单独",
    "06:00 gives three by 21:00.": "设为 06:00，到 21:00 就能用上三个。",
    "Sent through Claude Code.": "通过 Claude Code 发送。",
    "One tiny request, sent only to an account whose 5-hour window isn't running then.": "只发一条极小的请求，且只发给那时 5 小时窗口没在计时的账号。",
    "A computer asleep then sends it on waking, up to an hour late; later than that, the day is left be.": "届时电脑若在睡眠，醒来后一小时内补发；超过则跳过当天。",
    "Nothing is sent while the computer sleeps: a window that resets then starts when it wakes, and counts from then.": "电脑睡眠时不会发送：睡眠期间重置的窗口在唤醒后开启，从唤醒时开始计时。",
    "With Weekly and 5-hour on, a window that would still be running then isn't started on its reset: the windows follow one another from this time.": "同时开启「每周和 5 小时」时，届时仍在计时的窗口不在重置时开启：窗口从此时间起依次衔接。",
