    "Auto check-in": "自动签到",
    "{name}'s daily check-in, pressed by its plugin": "{name} 的每日签到，由它的插件来签",
    "On: magpie has the {name} plugin check each account in once a day, as Settings' Daily check-in does. Click to turn it off.": "已开启：magpie 每天让 {name} 插件给每个账号签到一次，和设置里的「每日签到」一样。点一下关闭。",
    "Have the {name} plugin check each account in once a day, as Settings' Daily check-in does": "让 {name} 插件每天给每个账号签到一次，和设置里的「每日签到」一样",
