    "{user}: {name} only gives check-in credits to its own app; check in in the {name} app": "{user}：{name} 只给自己的客户端发签到积分，请在 {name} App 里签到",
    "Trae CN refused this check-in (9074: too many taking part); check in in the Trae CN app": "Trae CN 拒绝了这次签到（9074 当前参与用户太多），请在 Trae CN App 里签到",
    "{user}: Trae CN refused this check-in (9074: too many taking part); check in in the Trae CN app": "{user}：Trae CN 拒绝了这次签到（9074 当前参与用户太多），请在 Trae CN App 里签到",
