    "On: magpie checks each WorkBuddy (China) account in once a day, as Settings' Daily check-in does. Click to turn it off.": "已开启：每天为每个 WorkBuddy 国内版账号签到一次，与设置中的「每日自动签到」为同一开关。点击关闭。",
