    // web search APIs (#419)
    "Web search": "联网搜索",
    "Search APIs": "搜索 API",
    "Search API": "搜索 API",
    "When a model can't search the web, magpie searches for it with these, in this order, and gives it what they found": "模型不能联网搜索时，按顺序用这些 API 代为搜索并返回结果",
    "Now done by {who}; these come after it": "目前由 {who} 代搜，这些排在它之后",
    "Asked before {who}, which searches when these fail": "先用这些搜索，都失败时再由 {who} 代搜",
    "Search first with": "优先使用",
    "MCP server": "MCP 服务器",
    "Cursor, Claude Desktop and other agents can add this search as an MCP server (Streamable HTTP), with a web_search tool and a web_fetch tool that reads a page by its URL. From another computer, send a gateway key as Authorization: Bearer <key>.": "Cursor、Claude Desktop 等智能体可以把这个搜索添加为 MCP 服务器（Streamable HTTP），提供 web_search 工具和按 URL 读取网页的 web_fetch 工具。从其他电脑访问时，请以 Authorization: Bearer <key> 发送网关密钥。",
    "Ask {name}": "启用 {name}",
    "Off: kept with its key, and never asked": "关闭：保留它和它的密钥，但不再调用",
    "On: asked in its turn": "开启：按顺序轮到时调用",
    "Image recognition MCP server": "识图 MCP 服务器",
    "Agents can add image recognition as an MCP server (Streamable HTTP) with one analyze_image tool, which reads an image with the Image recognition model from a file path, a URL or a data URL. From another computer, send a gateway key as Authorization: Bearer <key> and the image as a URL or data URL.": "智能体可以把识图添加为 MCP 服务器（Streamable HTTP），提供一个 analyze_image 工具：用识图模型读取文件路径、URL 或 data URL 中的图片。从其他电脑访问时，请以 Authorization: Bearer <key> 发送网关密钥，图片以 URL 或 data URL 传入。",
    "The other is asked when it fails": "失败时再用另一种",
    "Models that search by themselves": "自带联网搜索的模型",
    "Search with their provider's own search, or with magpie's, as every other model does": "用供应商自带的联网搜索，或像其他模型一样用 magpie 代搜",
    "Their own": "自带搜索",
    "magpie has nothing to search with: add a Search API above, or pick a provider under Searches for other models": "magpie 现在没有可用的搜索：请在上方添加搜索 API，或在「代搜供应商」里选一个供应商",
    "magpie's": "magpie 代搜",
    "When provider search is off, only configured Search APIs are used, for every model. Without a Search API, magpie does not add a search tool.": "关闭供应商代搜后，所有模型都只使用已配置的搜索 API；未配置时，Magpie 不添加搜索工具。",
    "Model search": "模型代搜",
    "No provider can search, so these are asked": "没有能搜索的供应商，由这些 API 来搜",
    "When provider search is off, only configured Search APIs are used. Without a Search API, magpie does not add a search tool. Providers' native web search is unchanged.": "关闭供应商代搜后，仅使用已配置的搜索 API；未配置时，Magpie 不添加搜索工具。供应商自带的联网搜索不受影响。",
    "Provider search is off; only these APIs are used": "已关闭供应商代搜，仅使用这些 API",
    "Searches for other models": "代搜供应商",
    "When a model can't search the web directly, the selected provider searches for it and returns the results. Searches may use the service's quota or incur charges; if the provider magpie picks fails, it tries other available sources, and a provider you select here gives way to the ones you add after it, in their order, then, when it can't search at all (out of quota or rate-limited), to other available sources, then to your Search APIs.": "当模型无法直接联网搜索时，由所选供应商代为搜索并返回结果。代搜可能消耗所用服务的额度或产生费用；magpie 自动选择的供应商失败时会尝试其他可用来源，在此手动选中的供应商失败时会按顺序换成你在它后面添加的供应商；若它完全搜不了（额度用完或被限流），再尝试其他可用来源，最后改用你配置的搜索 API。",
    "{who} didn't search {when}: {why}. {next} searched in its place.": "{who} {when}没能搜索：{why}。已由 {next} 代为搜索。",
    "{who} didn't search {when}: {why}. The ones after it didn't search either; add another provider after it, or a Search API.": "{who} {when}没能搜索：{why}。排在它后面的供应商也都没能搜索；可在它后面再添加一个供应商，或添加搜索 API。",
    "If it fails": "失败时依次换用",
    "These providers search in its place, in this order, when the one above fails; no other provider does.": "上面的供应商搜索失败时，按此顺序由这些供应商代为搜索；不会换用其他供应商。",
    "{who} didn't search {when}: {why}. No other provider searched in its place; pick Automatic or another provider, or add a Search API.": "{who} {when}没能搜索：{why}。没有换用其他供应商代搜；可改选“自动”或其他供应商，或添加搜索 API。",
    "it answered without searching the web, so its account or plan may not offer web search": "它没有联网搜索就直接回答了，它的账号或套餐可能不支持联网搜索",
    "no provider that searches": "没有能搜索的供应商",
    "{model}, its small model": "{model}（它的小模型）",
    "its web search": "它自带的联网搜索",
    "A Kimi Code plan ({names}) searches for its own models first, with its web search; for other models only when named here": "Kimi Code 套餐（{names}）的模型优先用套餐自带的联网搜索；其他模型仅在此处选中时使用",
    "{names} search for their own models first, with Gemini's Google Search": "{names} 的模型优先用 Gemini 自带的 Google 搜索",
    "it is no longer in magpie": "它已不在 magpie 里",
