    "These relays must be selected manually and are not used for automatic selection or fallback: {names}.": "以下中转服务需手动指定，不参与自动选择或自动回退：{names}。",
    "These providers can't be selected to search for other models with the current configuration: {names}. Their models can still get search results through other available search providers or configured search APIs.": "以下供应商在当前配置下不可选为代搜供应商：{names}。它们的模型仍可通过其他可用的代搜供应商或已配置的搜索 API 获取搜索结果。",
    "{names} and {n} more": "{names} 以及另外 {n} 个",
