    "Keys of {name}": "{name} 的密钥",
    "In turn spreads searches over the keys; in order uses the first until it is refused. A key refused lately is asked last.": "轮流：搜索分摊到各个密钥；按顺序：先用第一个，被拒后才用下一个。最近被拒的密钥最后才用。",
