    "its accounts and model picks as they were": "账号和选好的模型都照旧",
    "Sign out…": "退出登录…",
    "magpie forgets its accounts; adding it again signs in afresh": "移除 magpie 保存的账号；再次添加需重新登录",
    "Sign {name} out of magpie?": "在 magpie 里退出 {name}？",
    "magpie signs out the accounts it keeps for {name} and forgets them; adding {name} again signs in afresh. The account itself is left as it is.": "退出并移除为 {name} 保存的账号；再次添加 {name} 需重新登录。账号本身不受影响。",
    "magpie signs out the accounts it keeps for {name}; adding it again signs in afresh": "退出为 {name} 保存的账号；再次添加需重新登录",
    "{name} signed out": "已退出 {name}",
    "{agent} is signed in to {user} now: sign it in to another of its accounts first (Use on that account), then remove this one": "{agent} 当前登录的是 {user}：请先在另一个账号上点「使用」把 {agent} 切过去，再移除这个账号",
    "{agent} is signed in to {user}, the only account in magpie it can be signed in to, and magpie doesn't sign it out: add another account first, or sign out in {agent} itself, then remove this one": "{agent} 当前登录的是 {user}，这是 magpie 里它唯一能登录的账号，magpie 不会把它登出：请先添加另一个账号，或在 {agent} 里自己登出，再移除这个账号",
    "Signs Codex out of this account, as codex logout does": "让 Codex 退出这个账号，与 codex logout 相同",
    "{agent} is signed in to another of its accounts, and magpie forgets this one; the account itself is untouched": "{agent} 会先登录到它的另一个账号，magpie 再忘掉这个账号；账号本身不受影响",
    "Codex itself is signed out too, as codex logout does.": "Codex 本身也会退出登录，与 codex logout 相同。",
    "Sign {agent} out of {user}?": "让 {agent} 退出 {user}？",
