    "Where Codex, Claude Code and Grok Build compact a long conversation on these models; empty follows Long conversations, in their settings on the Agents page (else in Settings), and a size at or above a model's window runs it to its whole window": "Codex、Claude Code 和 Grok Build 在这些模型上压缩长对话的位置；留空按 Agent 页里它们设置中的「长对话」（否则在「设置」里），大于等于模型窗口则用完整窗口",
