    "No model or routing group matches": "没有匹配的模型或路由组",
    "When {name} is out of quota, rate limited or down, a request goes to these instead, top first. It only happens before any of the reply is sent, and {name} then sits out a minute.": "{name} 额度用完、限流或不可用时，请求按从上到下的顺序改发给这些模型。仅在回复开始前切换，之后 {name} 暂停使用一分钟。",
    "{agent} and the gateway use the one in use. Sessions already running keep theirs until restarted.": "{agent} 和网关使用标记为「使用中」的账号。已在运行的会话保持原账号，重启后切换。",
    "The gateway uses the first. Tick more and it moves on to the next when the one before it is out of quota. {agent} itself stays signed in as it is.": "网关优先用第一个账号；勾选多个时，前一个额度用完自动换下一个。{agent} 本身的登录不变。",
    "The gateway uses the first. Tick more and it moves on to the next when the one before it is out of quota.": "网关优先用第一个账号；勾选多个时，前一个额度用完自动换下一个。",
