    "Deprecated": "已弃用",
    "Some subscriptions are reached in ways their vendors' terms may not allow. So that magpie itself isn't banned over them, subscription providers are being decoupled from magpie and run by community plugins instead.": "部分订阅的接入方式可能违反厂商条款。为免 magpie 本体因此被封禁，订阅供应商正逐步移出 magpie，改由社区插件提供。",
