    "the vendor": "该厂商",
    "This link can't be imported: {e}": "这个链接无法导入：{e}",
    "Added from a link. Your prompts and this key will go to {hosts}; add it only if you trust the site that sent you here.": "从链接导入。你的提示词和此密钥将发往 {hosts}；仅在信任发来链接的网站时添加。",
    "From the link. Kept in ~/.config/magpie/providers.json, readable by you alone.": "来自链接。保存在 ~/.config/magpie/providers.json，仅你自己可读。",
