    "Kept in ~/.config/magpie/providers.json, readable by you alone. Nothing is read from your shell.": "保存在 ~/.config/magpie/providers.json，仅你本人可读。不读取 shell 中的任何内容。",
    "model ids, comma separated · e.g. gpt-5.5, claude-sonnet-5": "模型 ID，逗号分隔 · 例如 gpt-5.5, claude-sonnet-5",
    "Optional: Fetch models to pick from the vendor's list, or type ids; none picked, magpie asks for the list after saving.": "可选：用「获取模型」从供应商列表中勾选，或直接填写模型 ID；不选则保存后自动获取模型列表。",
    "Fetch models": "获取模型",
    "Ask the vendor for its model list with the URL and key typed, to pick from; nothing is saved": "用所填 URL 和密钥获取供应商的模型列表供勾选；不保存任何内容",
    "Asking the vendor…": "正在向供应商获取…",
    "The vendor's list is empty. Type the model ids instead.": "供应商的列表是空的，请直接填写模型 ID。",
    "No model here matches “{q}”.": "没有匹配“{q}”的模型。",
