    "Gemini compatible": "Gemini 兼容",
    "…/v1beta — Google's Gemini API (generateContent), or one that answers as it does; the key goes in x-goog-api-key": "…/v1beta — Google 的 Gemini API（generateContent），或与它应答方式相同的端点；密钥放在 x-goog-api-key 里",
