    "models.dev ids, e.g. openai, deepseek": "models.dev 上的 ID，例如 openai, deepseek",
    "Catalog": "目录",
    "Display names, reasoning levels and list prices for the models; for a gateway that serves several vendors, list them all, first match wins": "模型的显示名称、推理等级与官方价格；网关提供多家厂商的模型时全部列出，先匹配者优先",
    "Balance URL": "余额查询地址",
    "Balance request method": "余额查询方法",
    "How the Balance URL is asked: GET, or POST with no body for a vendor that answers only a POST": "余额查询地址的请求方法：GET，或不带请求体的 POST，用于只接受 POST 的接口",
    "Models URL": "模型列表地址",
    "Where the vendor lists its models, when that isn't under the base URL; asked with the key": "供应商的模型列表接口，不在基础地址下时填写；请求时会带上 Key",
    "Where the vendor tells what is left on the key, asked with it like a chat request; {key} in it or in a header is each key's own, for a vendor that takes the key in the URL (…?key={key}); shown on the Usage page": "查询 Key 余额的接口，像对话请求一样带 Key 请求；地址或请求头中的 {key} 替换为各 Key 自身的值，用于 Key 放在 URL 中的接口（…?key={key}）；结果显示在用量页",
    "Balance field": "余额字段",
    "Where the amount is in the reply, e.g. data.balance; it can be a sum with + - * / and brackets, e.g. data.total / 500000 or (1 - credits.used / 70) %; \"$\" in front adds the sign, \"%\" after it shows a percent, with a bar; several, each with a label, go apart by \";\", e.g. 5h: a.used / a.cap %; $credits.left; a list's items are a.*.used, or a[status=active].used for those that match, put in sum(), max(), min() or count(); an amount the reply hasn't shows \"—\" and the others still show": "金额在返回 JSON 中的位置，例如 data.balance；可用 + - * / 和括号计算，例如 data.total / 500000 或 (1 - credits.used / 70) %；前加 \"$\" 显示币种符号，后加 \"%\" 显示为百分比和进度条；多个金额用 \";\" 分隔，可各加标签，例如 5h: a.used / a.cap %; $credits.left；数组的每一项写作 a.*.used，只取符合条件的写作 a[status=active].used，放进 sum()、max()、min() 或 count() 汇总；某个金额在返回中取不到时显示 \"—\"，其他金额照常显示",
    "Balance": "余额",
    "Balances": "余额",
    "Updated {when}": "{when}更新",
    "Not used yet": "还没用过",
    "1 reset": "1 张重置卡",
    "{n} resets": "{n} 张重置卡",
