    "No model here matches “{q}”. Image, embedding and speech models aren't listed, as agents can't chat with them: pick an image model in Settings → Images.": "没有匹配“{q}”的模型。生图、向量和语音模型无法对话，不在此列出；生图模型请在 设置 → 图像 中选择。",
    "add a model id…": "添加模型 ID…",
