    "Test as Claude Code": "以 Claude Code 身份测试",
    "Asked as {agent} asks, for a relay that serves only {agent}": "按 {agent} 的请求方式发送，适用于只服务 {agent} 的中转站",
    "no Claude Code request has come through magpie yet: run Claude Code through magpie once, then test again": "还没有 Claude Code 请求经过 magpie：先通过 magpie 运行一次 Claude Code，再来测试",
    "Copy model ID": "复制模型 ID",
    "The number Claude Desktop's menu shows beside this model": "Claude Desktop 菜单在该模型旁显示的编号",
    "Model ID {model} copied": "已复制模型 ID {model}",
    "A classifier's models aren't sent test requests: Test under Endpoints asks Jev's endpoint for them.": "分类器模型不单独发测试请求：「端点」下的「测试」会向 Jev 端点检测它们。",
    "{name} is reached through its own API, which magpie translates each agent request for, so a test request can't be sent to it on its own. Ask the model from an agent to try it.": "{name} 使用自有接口，由 magpie 转换 Agent 的请求，无法单独发测试请求。请在 Agent 中使用该模型测试。",
    "{model} answered in {took}": "{model} 在 {took}内响应",
