    "Answered in {took}": "{took}内响应",
    "Pick a model first.": "请先选择模型。",
    "The name agents and magpie show for {id}; empty for its own": "Agent 和 magpie 为 {id} 显示的名称；留空则用默认名称",
    "{id} is called {name}": "{id} 已改名为 {name}",
    "{id} has its own name again": "{id} 已恢复默认名称",
    "Accepts images": "支持图片输入",
    "Models of {providers} aren’t listed until marked in their provider’s {names} › {images}": "{providers} 的模型需在供应商的「{names}」›「{images}」中勾选后才会列出",
    "Whether agents are told {id} can see images": "是否告诉 Agent {id} 能看图片",
    "{id} accepts images": "{id} 支持图片输入",
    "{id} does not accept images": "{id} 不支持图片输入",
    "Reasoning levels agents are offered": "提供给 Agent 的推理档位",
    "Reasoning levels agents are offered; none ticked: it is sent no reasoning field": "提供给 Agent 的推理档位；全不勾选则不发送任何推理参数",
    "No reasoning field sent": "不发送推理参数",
    "None ticked: magpie sends {id} no reasoning field, whatever effort the agent asks, as for a model that doesn't reason": "全不勾选：无论 Agent 要求什么推理强度，magpie 都不给 {id} 发送推理参数，与不推理的模型一样",
    "Its reasoning levels aren't known: tick the ones it takes": "推理档位未知：勾选它支持的档位",
    "{id}: {levels}": "{id}：{levels}",
    "Restore default": "恢复默认",
    "Its own name, every reasoning level it has, whether it sees images, the API it is asked on, the model it is the same as, its own id, and its list price": "恢复默认名称、全部推理档位、是否支持图片、请求所用的协议、它等同的模型、它自己的 ID，以及官方价格",
    "What {id} costs, in US dollars per million tokens, as the Usage page counts it; empty: its list price, shown greyed. A price set here isn't multiplied by the provider's price rate": "{id} 的价格，单位为美元 / 百万 tokens，用量页按它计费；留空即官方价格（灰字所示）。这里设的价格不再乘以供应商的价格倍率",
    "Off-peak price, the list's or one set here: the Usage page doubles it from 01:00 to 04:00 and 06:00 to 10:00 UTC, Monday to Friday{x}": "闲时价（官方价格或在此设置的价格）：周一至周五 UTC 01:00–04:00 与 06:00–10:00{x}，用量页按两倍计",
    "Off-peak price, the list's or one set here: the Usage page doubles it from 12:00 to 18:00 UTC, Monday to Friday": "闲时价（官方价格或在此设置的价格）：周一至周五 UTC 12:00–18:00，用量页按两倍计",
    ", except on Chinese public holidays": "（中国法定节假日除外）",
    "What {id} costs, in US dollars per million tokens, as the Usage page counts it; empty: what the other magpie counts it at, shown greyed. A price set here isn't multiplied by the provider's price rate": "{id} 的价格，单位为美元 / 百万 tokens，用量页按它计费；留空即另一台 magpie 计费用的价格（灰字所示）。这里设的价格不再乘以供应商的价格倍率",
    "Price, $ / 1M tokens": "价格（$ / 百万 tokens）",
    "{id} has no list price: give its input and output prices": "{id} 没有官方价格：请填写输入和输出价格",
    "A price is a number of dollars, 0 or more": "价格是 0 或以上的美元数",
    "Same as": "等同于",
    "Listed as": "列为",
    "The id magpie lists {id} by at this provider: agents, routing groups, the groups magpie finds, gateway keys and Usage all use it, and the provider is still asked for {own}. Empty: its own id": "magpie 在这个提供商列出 {id} 所用的 ID：智能体、路由组、magpie 找到的路由组、网关密钥和用量都用它，向提供商请求时仍用 {own}。留空：用它自己的 ID",
    "The model other providers serve that {id} is the same as: the routing groups magpie finds put them together, and what no list gives for {id} is that model's: its window, reply limit, reasoning levels, images and list price. Empty: by its own id": "{id} 等同于其他供应商的哪个模型：自动发现的路由组会将它们合并；任何列表都没给出的 {id} 信息（上下文窗口、回复上限、推理档位、图片输入和标价）都按那个模型的来。留空则按自身 ID 合并",
    "The API {id} is asked on. Auto: as the vendor's list says, else each URL the provider has; pick one when the vendor serves it on that one only": "{id} 请求所用的协议。自动：按供应商模型列表，否则依次尝试已填的各个地址；供应商仅在某协议上提供它时，选择该协议",
    "{id} is as its provider has it again": "{id} 已恢复为供应商的默认设置",
    "API this model is asked on": "这个模型请求所用的协议",
