    "Quitting magpie {v}…": "正在关闭 magpie {v}…",
    "magpie {v}, an older copy of this app, still serves the gateway": "更旧的 magpie {v}（这个应用的旧副本）仍在提供网关",
    "This magpie ({mine}) takes it over once its {n} request in flight finishes; until then agents' requests go through magpie {v}.": "当前 magpie（{mine}）会在它手上的 {n} 个请求完成后接管网关；在此之前，Agent 的请求仍经 magpie {v} 发出。",
    "This magpie ({mine}) takes it over once its {n} requests in flight finish; until then agents' requests go through magpie {v}.": "当前 magpie（{mine}）会在它手上的 {n} 个请求完成后接管网关；在此之前，Agent 的请求仍经 magpie {v} 发出。",
    "This magpie ({mine}) takes it over once it has no request in flight; until then agents' requests go through magpie {v}.": "当前 magpie（{mine}）会在它没有进行中的请求时接管网关；在此之前，Agent 的请求仍经 magpie {v} 发出。",
    "This magpie ({mine}) takes it over in a moment.": "当前 magpie（{mine}）马上接管网关。",
    "The gateway is served by magpie {v}, older than this app ({mine})": "网关由 magpie {v} 提供，比这个应用（{mine}）旧",
    "It runs as magpie serve, in a terminal or as the service. Agents' requests go through it without this version's fixes, and models set up here may not reach them. Update that magpie and start it again (magpie daemon restart, for the service), or quit it here and this app serves the gateway.": "它以 magpie serve 运行，在终端里或作为后台服务。Agent 的请求经它发出，不含当前版本的修复，这里设置的模型也可能用不了。请更新那个 magpie 并重新启动它（后台服务用 magpie daemon restart），或在这里关闭它，由这个应用提供网关。",
    "Agents' requests go through it without this version's fixes, and models set up here may not reach them. Quit it here and this app serves the gateway at once.": "Agent 的请求经它发出，不含当前版本的修复，这里设置的模型也可能用不了。在这里关闭它，这个应用会立即接管网关。",
    "The gateway is served by magpie {v}, newer than this app ({mine})": "网关由 magpie {v} 提供，比这个应用（{mine}）新",
    "Agents' requests go through it, and what this app writes for them may not match it. Update this magpie, or quit the newer one there.": "Agent 的请求经它发出，这个应用为它们写的设置可能与它不匹配。请更新当前 magpie，或在那边关闭较新的那个。",
    "The gateway is served by magpie {v}, a different build from this app ({mine})": "网关由 magpie {v} 提供，与这个应用（{mine}）不是同一个构建",
    "Agents' requests go through it, and what this app writes for them may not match it. Quit it there for this app to serve the gateway.": "Agent 的请求经它发出，这个应用为它们写的设置可能与它不匹配。请在那边关闭它，由这个应用提供网关。",
    "Restart gateway": "重启网关",
    "Start gateway": "启动网关",
    "Restarting the gateway…": "正在重启网关…",
    "Starting the gateway…": "正在启动网关…",
    "Port {port} is held by {path} (pid {pid}), which isn't magpie, so magpie leaves it alone. Quit it yourself, or move the gateway to another port in Settings.": "端口 {port} 被 {path}（pid {pid}）占用，它不是 magpie，所以 magpie 不会动它。请自行退出它，或在设置里把网关换到其他端口。",
    "Port {port} is forwarded by {path} (pid {pid}) to a container or a VM: the magpie {v} answering there runs inside it, out of this magpie's reach. Stop that container (docker ps lists it, docker stop <name> stops it, or stop it in OrbStack or Docker Desktop), or move this magpie's gateway to another port in Settings.": "端口 {port} 由 {path}（pid {pid}）转发到一个容器或虚拟机：在那里应答的 magpie {v} 运行在容器里，这个 magpie 管不到它。请停掉那个容器（docker ps 可以列出它，docker stop <名称> 停掉它，或在 OrbStack、Docker Desktop 里停止），或在设置里把这个 magpie 的网关换到其他端口。",
    "magpie can't see which process holds port {port}: it runs as another user or as administrator. Quit it there.": "magpie 看不到是哪个进程占用了端口 {port}：它以其他用户或管理员身份运行。请在那边退出它。",
    "magpie {v} (pid {pid}, {path}) runs as another user or as administrator, so this magpie can't quit it. Quit it there.": "magpie {v}（pid {pid}，{path}）以其他用户或管理员身份运行，当前 magpie 无法关闭它。请在那边退出它。",
    "magpie {v} (pid {pid}) didn't quit. End it in your system's process list (Activity Monitor, Task Manager).": "magpie {v}（pid {pid}）没有退出。请在系统的进程列表（活动监视器、任务管理器）里结束它。",
    "Something started magpie on port {port} again at once ({path}, pid {pid}): a login item or a service keeps it running (a LaunchAgent, a systemd unit, a scheduled task). Remove that, then try again.": "端口 {port} 上的 magpie 被立即重新启动了（{path}，pid {pid}）：有登录项或系统服务让它一直运行（LaunchAgent、systemd 单元、计划任务）。请先移除它，再重试。",
    "Port {port} is in use by {path} (pid {pid}): quit it, or move the gateway to another port in Settings.": "端口 {port} 被 {path}（pid {pid}）占用：请退出它，或在设置里把网关换到其他端口。",
    "Port {port} is in use by another program: quit it, or move the gateway to another port in Settings.": "端口 {port} 被其他程序占用：请退出它，或在设置里把网关换到其他端口。",
    "magpie {v} serves the gateway, and it isn't older than this one: quit it there to serve the gateway here.": "网关由 magpie {v} 提供，它不比当前版本旧：请在那边退出它，再由这里提供网关。",
    "The gateway couldn't be served here: {error}": "无法在这里提供网关：{error}",
    "not running": "未运行",
    "{n} agent routed through it": "{n} 个 Agent 经由此路由",
    "{n} agents routed through it": "{n} 个 Agent 经由此路由",
    "no agent routed through it yet": "尚无 Agent 经由此路由",
    "start it with magpie serve, or open magpie at login": "用 magpie serve 启动，或让 magpie 开机自启",
    "Copy the gateway URL": "复制网关地址",
    "Gateway URL": "网关地址",
