    "What was here before is the version of {when}: restore it to undo.": "恢复前的配置已备份为 {when} 的版本：恢复它即可撤销。",
    "Your providers, settings and profiles, without API keys or sign-ins, into a folder on this computer": "提供商、设置和配置方案（不含 API 密钥和登录信息），备份到本机的文件夹",
    "Your providers, settings, profiles and agents' models become this backup's. Providers added since are kept, and each keeps its API keys here.": "提供商、设置、配置方案和各 agent 的模型将变为这份备份中的内容。之后新加的提供商会保留，每个提供商在本机的 API 密钥也保持不变。",
