    "Restore from the server": "从服务器恢复",
    "This computer's setup becomes the one on the server. What is here now is kept first, to undo.": "用服务器上的配置覆盖本机，覆盖前先备份当前配置，可撤销。",
    "Restore…": "恢复…",
    "Restore from the server?": "从服务器恢复？",
    "This computer's {parts} become the ones on the server, as your other computers last synced them. Whatever was changed here since is replaced.": "本机的{parts}将换成服务器上的（其他电脑最后同步的版本），本机之后的改动会被替换。",
    "What is here now is sealed into the sync folder first, and Undo puts it back.": "当前配置会先加密备份到 sync 文件夹，可点「撤销」换回。",
