    "What another computer wrote into that file and has nowhere else is lost. If one of them synced it last, Sync now there may rebuild it instead.": "另一台电脑写进那个文件、别处没有的内容会丢失。如果是其他某台电脑最后同步的，在那台电脑上点「立即同步」可能可以直接修复。",
