    "Usage: this computer's calls, for the Usage page on the others": "用量：本机的请求，在其他电脑的用量页里显示",
    "Usage goes as a file a day: times, tokens, models and costs, never what was said. Turn it on on each computer that shares its own.": "用量每天一个文件：时间、token、模型和费用，不含对话内容。每台要共享用量的电脑都需各自打开。",
