    "Providers with the same id are replaced; one that came without a key keeps the key it has here. The library replaces the one here, which is kept with its backups.": "同 id 的供应商会被替换；不带 Key 的保留本机已有的 Key。资源库将替换本机资源库，原内容保存在备份中。",
