    "ZCode: no GLM Coding Plan, and no free Start Plan — subscribe to a GLM Coding Plan to use this account": "ZCode：没有 GLM Coding Plan，也没有免费的体验套餐 — 请订阅 GLM Coding Plan 后使用该账号",
