    "Network and sharing": "网络与共享",
    "Model ids without the provider": "不带供应商的模型 ID",
    "The gateway’s model list also names each model by its own id, as gpt-5.6-sol beside codex/gpt-5.6-sol, for apps moved from another proxy. One that several providers serve goes to them in the Providers order": "网关的模型列表还会以模型自己的 ID 列出每个模型，如 codex/gpt-5.6-sol 旁的 gpt-5.6-sol，供从其他代理迁来的应用使用。多个供应商都提供的模型，按“供应商”中的顺序发往它们",
    "Busy models last": "繁忙的模型靠后",
    "A model its plugin says is busier than this goes after the others a request could go to, as its vendor makes it wait. One with no load reported in the last 5 minutes keeps its place": "插件报告负载高于此值的模型，排在请求可去的其他模型之后，因为它的供应商会让请求排队等待。最近 5 分钟内没有报告负载的模型保持原位",
    "Over {n}%": "高于 {n}%",
    "A load is in percent, as the plugin reports it: 100 is all its vendor serves at once, and past 100 requests queue (200 is twice that). Type 1 to 9999": "负载以百分比计，由插件报告：100 表示供应商同时能处理的全部量，超过 100 表示请求在排队（200 即两倍）。输入 1 到 9999",
