    "The `magpie` command is a copy": "终端里的 `magpie` 命令是一份拷贝",
    "{file} was damaged (the computer likely stopped mid-write), so magpie restored it from its backup of {time}. A change made after that may be missing; the damaged file is kept beside it.": "{file} 已损坏（多半是电脑在写入途中停机），magpie 已从 {time} 的备份恢复。之后的改动可能缺失；损坏的文件保留在旁边。",
    "{file} was damaged (the computer likely stopped mid-write), so magpie restored it from its backup. A change made after that may be missing; the damaged file is kept beside it.": "{file} 已损坏（多半是电脑在写入途中停机），magpie 已从备份恢复。之后的改动可能缺失；损坏的文件保留在旁边。",
    "The `magpie` command at {path} is a copied file, not the installer's link to the app: it won't follow the app's updates, and an old copy can break what a new one fixed. Re-run the installer, or link it by hand.": "`magpie` 命令（{path}）是拷贝的文件，不是安装脚本建立的应用链接：不会随应用更新，旧拷贝可能使新版的修复失效。请重新运行安装脚本，或手动建立链接。",
    "Update button": "更新按钮",
    "Shows in the header when a newer magpie is out": "magpie 有新版本时显示在顶栏",
    "Hidden for {v} until a newer version is out": "{v} 已隐藏，更新的版本发布时再显示",
