    "{v} didn't start on this computer: Windows' Smart App Control (or another app control policy) blocked the new version, which isn't signed. magpie stays on {cur}. Download it and run it yourself, or turn Smart App Control off and check again": "{v} 没能在这台电脑上启动：Windows 的「智能应用控制」（或其他应用控制策略）拦下了未签名的新版本，magpie 仍是 {cur}。可以下载新版本自己运行，或关掉智能应用控制后再检查更新",
