    "macOS is running magpie from a temporary copy, so it can't update itself; move magpie to Applications and open it from there.": "macOS 正从临时副本运行 magpie，无法自动更新；请将 magpie 移到「应用程序」文件夹后从那里打开。",
    "magpie is running from its disk image, so it can't update itself; drag it to Applications and open it from there.": "magpie 正从磁盘映像运行，无法自动更新；请将它拖到「应用程序」文件夹后从那里打开。",
    "magpie can't write to the folder it runs from ({dir}), so it can't update itself; move it to a folder you can write to and open it from there.": "magpie 无法写入它所在的文件夹（{dir}），所以无法自动更新；请把它移到你有写入权限的文件夹，再从那里打开。",
    "{manager} installed magpie ({pkg}), so {manager} updates it, not magpie: {cmd}": "{manager} 安装了 magpie（{pkg}），所以由 {manager} 更新它，而不是 magpie 自己：{cmd}",
    "{manager} installed magpie, so {manager} updates it, not magpie.": "由 {manager} 安装的 magpie 由 {manager} 更新，而不是 magpie 自己。",
    "magpie runs in a container, so it can't update itself; pull the new image (docker pull ghcr.io/yetone/magpie:latest) and recreate the container.": "magpie 运行在容器里，无法自动更新；请拉取新镜像（docker pull ghcr.io/yetone/magpie:latest）并重新创建容器。",
