    "A conversation stays with the account or key that answered it and never moves to another, even past its usage cap: when that one is rate limited or out of quota, the error goes to the agent. New conversations are routed as usual.": "会话始终留在回答它的账号或密钥上，绝不换到别的，即使超过其用量上限也一样：它被限流或额度用完时，错误直接交给智能体。新会话照常路由。",
