    "In magpie": "magpie 内耗时",
    "One rate limited while it still has quota rests as long as the vendor asks, then takes its place in the order again.": "仍有额度却被限流的账号按厂商要求休息，之后回到原位继续使用。",
    "One rate limited (429) while it still has quota goes to the back of the order, behind every one not rate limited since, and comes round again once those ahead of it are rate limited in turn — so the load goes round rather than back to the first each time. Out of quota, it rests as usual. Kept until magpie restarts.": "仍有额度却被限流（429）的账号排到最后，位于此后所有未被限流的账号之后；前面的账号依次被限流后才再轮到它，负载因此轮转，而非每次回到第一个。额度用完的照常休息。此顺序保留到 magpie 重启。",
