    "The address Jev is asked at; paste the one from your gateway's docs, e.g. Cloudflare's …/accounts/<account id>/ai/run": "Jev 的请求地址；可直接粘贴网关文档中的地址，例如 Cloudflare 的 …/accounts/<账户 ID>/ai/run",
    "Routing groups name its models as {id} for their classifier": "路由组以 {id} 把它的模型选作判断模型",
    "A decision API on System One (TypeSafe's Jev, a gateway's, or Bailian's decision model) — what a routing group asks as a turn begins": "System One 协议的决策 API（TypeSafe 的 Jev、网关提供的，或阿里云百炼决策模型），路由组在每轮开始时询问它",
    "a decision API's root, POST …/systemone under it: its models are a routing group's classifier, never an agent's": "决策 API 的根地址，在其下 POST …/systemone：它的模型只作路由组的分类器，不给 Agent 使用",
