    "A conversation stays with the account or key that answered it while what the vendor cached of it is worth keeping — within a turn always, across turns while it's fresh.": "厂商缓存仍有价值时，会话留在回答过它的账号或 Key 上：一轮之内始终保持，跨轮则在缓存新鲜时保持。",
    "A conversation stays with the account or key that answered it for the whole session, while it can answer.": "会话始终留在回答过它的账号或 Key 上，只要它仍能回答。",
    "A conversation stays put within a turn, while the agent sends tool results back; when you speak again, routing decides afresh.": "一轮之内（Agent 回传工具结果时）不换；你再次发言时，路由重新决定。",
