    "WorkBuddy refuses chats from Codex and Claude Code (their system prompt); use it from Hermes, OpenCode or Pi, or add another provider to this group": "WorkBuddy 会因系统提示词拒绝 Codex 和 Claude Code 的对话；请在 Hermes、OpenCode 或 Pi 中使用，或在此分组中再加一个供应商",
    "Antigravity answers this 429 to the system prompt of Claude Code and the Claude Agent SDK (Claude Desktop's chats) whatever quota is left, so it is not a quota and waiting won't help; use another provider for these chats, or put one after Antigravity in a routing group": "Antigravity 对 Claude Code 和 Claude Agent SDK（Claude Desktop 的对话）的系统提示词都会回这个 429，与剩余额度无关，所以这不是额度用尽，等待也不会好；请用其他供应商处理这些对话，或在路由分组中把另一个供应商排在 Antigravity 之后",
    "Antigravity answers this 429 to Codex's own system prompt for GPT-5 models whatever quota is left, so it is not a quota and waiting won't help; a Codex chat begun on a GPT model keeps that prompt after a model switch or a fork, so start a new chat on this model": "Antigravity 对 Codex 给 GPT-5 模型的系统提示词都会回这个 429，与剩余额度无关，所以这不是额度用尽，等待也不会好；在 GPT 模型上开始的 Codex 对话切换模型或分叉后仍带着这段提示词，请在这个模型上新开一个对话",
    "Antigravity answers this 429 to Hermes Agent's earlier default persona (its SOUL.md) whatever quota is left, so it is not a quota and waiting won't help; Hermes' current default persona goes through, so put it in SOUL.md, or use another provider for these chats": "Antigravity 对 Hermes Agent 旧版默认人设（SOUL.md）都会回这个 429，与剩余额度无关，所以这不是额度用尽，等待也不会好；Hermes 当前的默认人设可以通过，请把它写进 SOUL.md，或为这些对话换用其他提供商",
    "the provider's network firewall blocked requests from this IP; wait a while, or switch to another network or proxy": "供应商的网络防火墙拦截了此 IP 的请求；请稍后再试，或更换网络或代理",
    "ZCode's risk control blocked this account for unusual activity (code 3012); it rests, and the group's other providers are used. If the ZCode app fails on this account too, only ZCode support can lift the block": "ZCode 风控因异常行为封禁了这个账号（代码 3012）；它会暂停使用，改用此分组中的其他供应商。如果用这个账号在 ZCode 官方 App 里也失败，只有 ZCode 客服能解除",
