    "Select none": "全不选",
    "Vendor's list": "供应商列表",
    "Picked only": "仅所选",
    "Serve the vendor's list, up to {n} of it (dashed), models it lists later too": "提供供应商的列表，最多 {n} 个（虚线框），之后新上的模型也包括在内",
    "Serve only the models picked": "只提供勾选的模型",
    "Usage only": "仅看用量",
    "Best in family": "每系最新",
    "Best in family: agents see the newest model of each family it lists (dashed), up to {n}. A newer one it lists later takes the old one's place.": "每系最新：Agent 看到它列表里每个系列最新的模型（虚线框），最多 {n} 个。之后上了更新的，会自动替换旧的。",
    "Route nothing to it: no agent or routing group uses its models, and those it lists later aren't added. Its balance and usage still show.": "不往它路由：Agent 和路由分组都不使用它的模型，之后新上的模型也不会加进来。余额和用量照常显示。",
    "usage only": "仅看用量",
    "Vendor's list: agents don't see it, the routing groups its models are in use up to {n} of it (dashed). Click a model to pick just it.": "供应商列表：Agent 看不到，模型所在的路由分组最多使用其中 {n} 个（虚线框）。点击模型可单选。",
    "Vendor's list: agents see up to {n} of its models (dashed), and those it lists later. Click a model to pick just it.": "供应商列表：Agent 看到最多 {n} 个模型（虚线框），之后新上的也会看到。点击模型可单选。",
    "Free only": "只选免费",
    "Pick only the free models (those the filter shows), unpicking the others": "只选中免费模型（有筛选时只选筛出来的），其余取消选中",
    "Working only": "只选可用",
    "Unpicked 1 model that didn't answer": "已取消选中 1 个没有响应的模型",
