    "{n} updates": "{n} 个更新",
    "Newer versions of your plugins are out: update them under Installed": "你的插件有新版本，在「已安装」里更新",
    "magpie community": "magpie 社区",
    "Written for magpie by its community, in github.com/magpie-community/plugins": "由 magpie 社区编写，源码在 github.com/magpie-community/plugins",
    "{n}/week": "{n}/周",
    "{n} downloads on npm last week": "上周在 npm 下载 {n} 次",
