    "Replaces built-in": "替代内置",
    "magpie's own sign-in to this subscription is deprecated: this plugin takes its place, and accounts signed in there move to it": "magpie 内置的此订阅登录已弃用：由此插件接替，内置里登录的账号会迁到插件",
    "magpie's own sign-in to this subscription is deprecated: this plugin takes its place, and accounts signed in there move to it.": "magpie 内置的此订阅登录已弃用：由此插件接替，内置里登录的账号会迁到插件。",
    "Search plugins and npm…": "搜索插件和 npm…",
