    "npm's own": "npm 官方源",
    "Use the registry your .npmrc, .bunfig.toml or shell names, or npm's own": "改用 .npmrc、.bunfig.toml 或终端环境中设置的源，都没有则用 npm 官方源",
    "Download the plugin list, plugins and Bun from mirrors in China first (npmmirror, jsDelivr), their official addresses after. Each is a copy of the very file, checked as the original is": "插件列表、插件和 Bun 优先从国内镜像（npmmirror、jsDelivr）下载，失败再用官方地址。镜像文件与官方相同，校验方式一致",
    "Search plugins": "搜索插件",
    "Couldn't load the plugins: {error}": "无法加载插件：{error}",
    "written for magpie, checked against its own sign-ins": "为 magpie 编写，与内置登录对照验证过",
    "Suggested": "推荐",
    "On npm": "npm 上的插件",
    "OpenCode plugins and pi packages anyone published — read what one does before you install it": "任何人都可发布的 OpenCode 插件和 pi 包，安装前请先了解它做什么",
    "Type two letters or more to search npm": "输入两个及以上字符以搜索 npm",
    "Nothing else on npm": "npm 上没有更多了",
    "No plugin called “{q}”": "没有叫「{q}」的插件",
    "Plugins extend magpie": "插件扩展 magpie",
    "A plugin can also run in magpie's gateway on what agents send and get back, pick which account a routing asks, give every agent tools, connect an agent, or add a page of its own.": "插件还可以在 magpie 网关里处理 Agent 发出和收到的内容、决定路由该用哪个账号、给每个 Agent 提供工具、接入一个 Agent，或加一个自己的页面。",
    "Write a plugin": "编写插件",
    "Gives every agent tools of its own, through magpie's MCP server": "通过 magpie 的 MCP 服务器，给每个 Agent 提供它自己的工具",
    "Tools for agents": "给 Agent 的工具",
    "tools every agent can call, through magpie's MCP server": "每个 Agent 都能调用的工具，经由 magpie 的 MCP 服务器",
    "Pages": "页面",
    "pages of their own in magpie's window, each shut off from the rest and reading only what it lists": "在 magpie 窗口里自成一页，与其他部分隔离，只能读取它列出的内容",
    "Plugins sign in to coding plans and make their requests; the models then work in every agent, like any provider's. They're OpenCode's provider plugins or pi's packages, run on Bun.": "插件负责登录编程套餐并发出请求，其模型可像其他供应商的一样用于所有 agent。插件为 OpenCode 的供应商插件或 pi 扩展包，运行在 Bun 上。",
    "A plugin is someone else's code with your sign-in or your requests: install the ones you trust.": "插件是他人的代码，会拿到你的登录或看到你的请求：只安装你信任的。",
    "Have one in mind?": "已有想装的？",
    "npm package or a folder on this computer": "npm 包名，或本机上的文件夹",
    "npm package, GitHub repo (github:owner/repo) or a folder": "npm 包名、GitHub 仓库（github:owner/repo）或本机文件夹",
    "Fetches it from {repo} again": "重新从 {repo} 获取",
    "Couldn't ask {repo} for its newest commit: {error}": "没能向 {repo} 查询最新提交：{error}",
    "{have} installed, {repo} is at {head}": "已安装 {have}，{repo} 已到 {head}",
    "The commit of {repo} installed": "已安装的 {repo} 提交",
    "New commits": "有新提交",
    "{head} is the newest commit of {repo}": "{head} 是 {repo} 的最新提交",
    "Choose a folder on this computer": "选择本机上的一个文件夹",
    "Choose a folder": "选择文件夹",
    "No plugins yet": "还没有插件",
    "Install a subscription or a middleware from Discover; a subscription signs in from here.": "在「发现」中安装订阅或中间件；订阅在这里登录。",
    "Discover plugins": "发现插件",
