    "Couldn't check for updates: {error}": "无法检查更新：{error}",
    "Couldn't check": "无法检查",
    "npm couldn't be reached — check your connection or proxy": "无法连接 npm，请检查网络或代理",
    "npm is turning requests away for now (too many); try again in a few minutes": "npm 暂时拒绝请求（请求过多），请几分钟后再试",
    "npm doesn't have it": "npm 上没有这个包",
    "npm answered with an error: {error}": "npm 返回错误：{error}",
    "v{have} installed, v{v} on npm": "已安装 v{have}，npm 上有 v{v}",
    "v{v} is the newest on npm": "v{v} 是 npm 上的最新版本",
    "magpie updates it by itself within the hour; Update does it now": "一小时内自动更新；点“更新”立即更新",
    "Auto-updated": "已自动更新",
    "Middleware": "中间件",
    "Gateway middleware": "网关中间件",
    "Options": "选项",
    "The options it runs with": "它运行时用的选项",
    "It runs with no options; its package suggests some": "它没有设置选项，包里有建议的选项",
    "Applied to the next request": "下一个请求起生效",
    "Not set: these are its package's example": "未设置：这是包里给的示例",
    "Not JSON: {error}": "不是 JSON：{error}",
    "Options are a JSON object": "选项须是一个 JSON 对象",
    "{name}'s options saved": "{name} 的选项已保存",
    "{name}'s options cleared": "{name} 的选项已清空",
    "Runs it with no options": "不带选项运行它",
    "Signs in to a subscription and serves its models": "登录一个订阅，提供它的模型",
    "runs in magpie's gateway on what every agent sends and gets back, whichever provider serves it": "在 magpie 的网关里处理每个 agent 发出的请求和收到的回复，不论由哪个供应商提供",
    "Runs in magpie's gateway on the requests your agents send and on the replies": "在 magpie 网关里运行，处理智能体发出的请求和收到的回复",
    "Middleware didn't load: {error}": "中间件没有加载：{error}",
    "Adds an agent magpie has no setup of its own for: pick its model on the Agents page and it goes through magpie": "添加一个 magpie 没有内置的 Agent：在 Agent 页选好模型，它就走 magpie",
    "agents magpie has no setup of its own for, connected to it as its own are": "magpie 没有内置的 Agent，接入方式和内置的一样",
    "Agent didn't load: {error}": "Agent 没有加载：{error}",
