    "onEvent sees only {events} events": "onEvent 只处理 {events} 事件",
    "A failed call leaves the request or reply as it was": "调用失败时，请求或回复保持原样",
    "Last: {error}": "最近一次：{error}",
    "magpie updated it from v{from} to v{to} on {date}": "magpie 已于 {date} 自动将它从 v{from} 更新到 v{to}",
