    "Plugins are other people's code: they sign in and make the requests, or see them as middleware.": "插件是他人的代码：由它登录并发出请求，或作为中间件看到请求。",
    "No README": "没有 README",
    "npm didn't answer: {error}": "npm 没有响应：{error}",
    "Couldn't read the folder's README: {error}": "无法读取该文件夹的 README：{error}",
    "More in Plugins": "插件中还有更多",
    "Subscriptions magpie doesn't sign in to itself: install a plugin for one in the Plugins tab": "magpie 未内置的订阅：在「插件」页安装对应插件即可",
    "Agents magpie has no setup of its own for: install a plugin for one in the Plugins tab, and it is listed here": "magpie 未内置的 Agent：在「插件」页安装对应插件，它就会出现在这里",
