    "Try it": "试一试",
    "Paste text an agent might send: it is masked here as a request would be, and kept nowhere": "粘贴一段智能体可能发送的文本：会像真实请求一样在本机脱敏，且不保存",
    "Deploy with key sk-proj-… and mail ops@company.com": "用密钥 sk-proj-… 部署，发邮件给 ops@company.com",
