    "Masking is off: this is what Mask secrets and Mask personal data would do": "脱敏已关闭：下面是开启“脱敏密钥”和“脱敏个人信息”后的效果",
    "1 value went to the vendor as written, as you set": "1 个值按你的设置原样发给了厂商",
